#Rosalind DNA count
from traitlets import Tuple


dna = ""
count_a = dna.count("A")
count_c = dna.count("C")
count_g = dna.count("G")
count_t = dna.count("T")

print(count_a, count_c, count_g, count_t)

def count_nucleotides(dna: str) -> Tuple[int, int, int, int]:

    clean_dna = dna.strip()

    count_a = clean_dna.count("A")
    count_c = clean_dna.count("C")
    count_g = clean_dna.count("G")
    count_t = clean_dna.count("T")
    return (count_a, count_c, count_g, count_t)
print(count_nucleotides(dna))

